    private fun seed(
        id: String,
        name: String,
        muscleGroup: String,
        secondaryMuscles: String,
        equipment: String,
        difficulty: String,
        movementType: String,
        category: String,
        instructions: String,
        cautions: String,
        trackingUnit: String = "kg",
    ) = ExerciseEntity(
        id = "builtin.$id",
        name = name,
        muscleGroup = muscleGroup,
        secondaryMuscles = secondaryMuscles,
        equipment = equipment,
        difficulty = difficulty,
        movementType = movementType,
        category = category,
        instructions = instructions,
        cautions = cautions,
        trackingUnit = trackingUnit,
